"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  EmojiPicker,
  EmojiPickerContent,
  EmojiPickerGroup,
  EmojiPickerHeader,
  EmojiPickerInput,
  EmojiPickerList,
  EmojiPickerPreview,
  EmojiPickerSkinTone,
} from "@/components/ui/emoji-picker"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"

export interface EmojiPickerPopoverProps {
  value?: string
  defaultValue?: string
  onEmojiSelect?: (emoji: string) => void
  placeholder?: string
  align?: "start" | "center" | "end"
  sideOffset?: number
  className?: string
}

export function EmojiPickerPopover({
  value,
  defaultValue = "😀",
  onEmojiSelect,
  placeholder = "Search emoji...",
  align = "start",
  sideOffset = 8,
  className,
}: EmojiPickerPopoverProps) {
  const [open, setOpen] = React.useState(false)
  const [uncontrolledValue, setUncontrolledValue] = React.useState(defaultValue)
  const selectedEmoji = value ?? uncontrolledValue

  const handleEmojiSelect = React.useCallback(
    (emoji: string) => {
      if (value === undefined) {
        setUncontrolledValue(emoji)
      }
      onEmojiSelect?.(emoji)
      setOpen(false)
    },
    [onEmojiSelect, value]
  )

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="outline"
          size="icon"
          aria-label="Select emoji"
          className={className}
        >
          <span className="text-lg leading-none">{selectedEmoji}</span>
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align={align}
        sideOffset={sideOffset}
        className="w-auto border-none bg-transparent p-0 shadow-none"
      >
        <EmojiPicker onEmojiSelect={handleEmojiSelect}>
          <EmojiPickerHeader>
            <EmojiPickerInput autoFocus placeholder={placeholder} />
          </EmojiPickerHeader>
          <EmojiPickerGroup>
            <EmojiPickerList containerHeight={320} />
          </EmojiPickerGroup>
          <EmojiPickerPreview>
            {({ previewedEmoji }) => (
              <>
                {previewedEmoji ? (
                  <EmojiPickerContent />
                ) : (
                  <span className="px-1 text-xs text-muted-foreground">
                    Pick an emoji…
                  </span>
                )}
                <EmojiPickerSkinTone />
              </>
            )}
          </EmojiPickerPreview>
        </EmojiPicker>
      </PopoverContent>
    </Popover>
  )
}
